    /// <summary>Authors only the reserved Mapping Conduit and reads the current solo configuration.</summary>
    public static class ArchiveMappingPolish
    {
        const string Folder=ArchiveTopicSetup.Folder,Prefabs=Folder+"/Art/Prefabs/",Kit=Prefabs+"Archive_T08_Mapping_Conduit.prefab";
        static Mesh cube,octagon,ring,crystal;static TMP_FontAsset font;static Material stone,gold,labels,blue,receiver,emitter,ink;
        [MenuItem("Tools/Logic Legends/Open Archive/Topics/Polish T8 Mapping Conduit")]
        public static string Apply(){
            if(EditorApplication.isPlayingOrWillChangePlaymode||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new InvalidOperationException("Use stopped Play Mode and a saved scene.");AuditSolo();
            var primitive=GameObject.CreatePrimitive(PrimitiveType.Cube);cube=primitive.GetComponent<MeshFilter>().sharedMesh;Object.DestroyImmediate(primitive);
            octagon=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_BeveledOctagon.asset");ring=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_InlayRing.asset");crystal=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_RuleCrystal.asset");
            font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/RulesOfInferenceUI/InferenceBody.asset");stone=Mat("Archive_Topic_Stone");gold=Mat("Archive_Topic_BrassInlay");labels=Mat("Archive_Topic_WorldLabels");blue=ColorMat("Archive_T8_MappingBlue",new Color(.16f,.67f,1));ink=ColorMat("Archive_T8_Ink",new Color(.04f,.14f,.18f));
            emitter=CrystalMat("Archive_T8_EmitterCrystal",new Color(.16f,.67f,1));receiver=CrystalMat("Archive_T8_ReceiverCrystal",new Color(.26f,.87f,.77f));
            var input=Port(false);var output=Port(true);var answer=Answer();var arrow=Arrow();var kit=PrefabUtility.LoadPrefabContents(Kit);
            try{
                var before=kit.GetComponentsInChildren<Collider>(true).Select(EditorJsonUtility.ToJson).ToArray();
                foreach(var old in kit.transform.Cast<Transform>().Where(t=>new[]{"T8_Visual_Identity","Mapping_Pylon_Foot","Mapping_Conduit","Seal_Inlay"}.Contains(t.name)).ToArray())Object.DestroyImmediate(old.gameObject);
                var root=new GameObject("T8_Visual_Identity").transform;root.SetParent(kit.transform,false);
                foreach(float x in new[]{-4.5f,4.5f})Part(root,"Crystal_Channel_Inlay",cube,gold,new Vector3(x,.07f,.3f),new Vector3(.035f,.012f,10.2f));
                foreach(var value in new[]{new{label="DOMAIN",x=-4.5f},new{label="CODOMAIN",x=4.5f}}){var text=Text(root,value.label,value.label,new Vector3(value.x,.09f,5.65f),new Vector2(3.5f,.65f),3.5f);text.transform.localRotation=Quaternion.Euler(90,180,0);text.color=new Color(.05f,.28f,.33f);}
                var entry=Text(root,"Conduit_Entry_Inscription","SELECT AN INPUT   →   CONNECT AN OUTPUT",new Vector3(0,.09f,7.0f),new Vector2(7.3f,.55f),3.1f);entry.transform.localRotation=Quaternion.Euler(90,180,0);entry.color=new Color(.05f,.28f,.33f);
                var art=kit.GetComponent<ArchiveMappingPresentation>();if(art==null)art=kit.AddComponent<ArchiveMappingPresentation>();art.emitterPrefab=input;art.receiverPrefab=output;art.answerPrefab=answer;art.arrowMesh=arrow;art.beamMaterial=blue;art.arrowMaterial=blue;art.sparkMesh=crystal;art.sparkMaterial=Mat("Archive_T1_Sparks");
                art.selectSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Assets/Sounds Effects/Small Sound Kit/Magic/Mgc_Ice_Arrow_Cast_01.wav");art.connectSound=art.selectSound;art.undoSound=art.selectSound;art.correctSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Graph/Correct.wav");art.incorrectSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Assets/Sounds Effects/Small Sound Kit/Magic/Mgc_Electric_Hit_01.wav");
                art.progressMarks=new Renderer[5];for(int i=0;i<5;i++){float x=(2-i)*.65f;Part(root,"Mapping_Progress_Brass_"+i,octagon,gold,new Vector3(x,.07f,6.4f),new Vector3(.48f,.07f,.48f));art.progressMarks[i]=Part(root,"Mapping_Progress_Seal_"+i,octagon,blue,new Vector3(x,.11f,6.4f),new Vector3(.33f,.025f,.33f)).GetComponent<Renderer>();}
                var station=kit.GetComponent<ArchiveTopicStation>();station.title.text="T8  FUNCTIONS & RELATIONS\nMapping Conduit";station.board.text="THE MAPPING CONDUIT\nDomain → Codomain\nRead the Book to begin.";station.GetComponentInChildren<ArchiveAnimatedBook>().bookRig.localScale=Vector3.one*.75f;
                if(!before.SequenceEqual(kit.GetComponentsInChildren<Collider>(true).Select(EditorJsonUtility.ToJson)))throw new InvalidOperationException("T8 collision changed.");PrefabUtility.SaveAsPrefabAsset(kit,Kit);
            }finally{PrefabUtility.UnloadPrefabContents(kit);}
            return "Saved T8 Mapping Conduit, three reusable props and a directed-arrow mesh. Original solo, island and navigation preserved.";
        }
        public static string AuditSolo(){
            var preview=EditorSceneManager.OpenPreviewScene("Assets/Scenes/Functions and Relations.unity");float seconds=0,penalty=0;MappingChallengeCatalog source=null;int managers=0,pedestals=0;
            try{var found=preview.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<FunctionsRelationsStageManager>(true)).ToArray();managers=found.Length;if(managers!=1)throw new InvalidOperationException("Expected one current solo mapping manager.");var data=new SerializedObject(found[0]);seconds=data.FindProperty("startingSeconds").floatValue;penalty=data.FindProperty("wrongAnswerPenalty").floatValue;source=data.FindProperty("catalog").objectReferenceValue as MappingChallengeCatalog;pedestals=data.FindProperty("classificationPedestals").arraySize;}finally{EditorSceneManager.ClosePreviewScene(preview);}
            var archive=AssetDatabase.LoadAssetAtPath<ArchiveTopicCatalog>(Folder+"/Archive_Topic_Catalog.asset");bool same=archive.mappings==source;var result=new{passed=seconds==600&&penalty==10&&source!=null&&source.ChallengeCount==5&&source.ChallengeGroups.All(g=>g.variants.Count==10)&&pedestals==3&&same,sourceScene="Assets/Scenes/Functions and Relations.unity",controller="FunctionsRelationsStageManager",managers=managers,startingSeconds=seconds,incorrectPenaltySeconds=penalty,classificationPedestals=pedestals,sharedCatalog=same,sourceCatalog=AssetDatabase.GetAssetPath(source),groups=source.ChallengeGroups.Select(g=>new{g.stageName,variants=g.variants.Count}).ToArray(),adaptations=new[]{"Existing shared session and commands","Solo ten-minute remaining clock pauses at solved Book gates","Wrong work retained; timeout retries keep solved team progress","Three classification choices in the solo order","Four Domain and four Codomain crystals, fixed arrows and range feedback"}};
            Directory.CreateDirectory(Folder+"/Testing/Reports");File.WriteAllText(Folder+"/Testing/Reports/T8SoloAudit.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));if(!result.passed)throw new InvalidOperationException("Solo mapping audit differs from the expected current setup.");return "Read the current solo scene, fifty variants and three-pedestal classification.";
        }
        static GameObject Port(bool target){var root=new GameObject(target?"Archive_T8_ReceiverPort":"Archive_T8_EmitterPort");Part(root.transform,"Carved_Base",octagon,stone,new Vector3(0,.08f,0),new Vector3(1.25f,.22f,1.25f));Part(root.transform,"Conduit_Ring",ring,gold,new Vector3(0,.20f,0),Vector3.one*1.02f);Part(root.transform,"Short_Column",cube,stone,new Vector3(0,.45f,0),new Vector3(.34f,.5f,.34f));Part(root.transform,"Column_Cap",octagon,gold,new Vector3(0,.72f,0),new Vector3(.52f,.12f,.52f));var pivot=new GameObject("Crystal_Pivot").transform;pivot.SetParent(root.transform,false);pivot.localPosition=Vector3.up*1.18f;Part(pivot,"Crystal",crystal,target?receiver:emitter,Vector3.zero,new Vector3(.7f,.85f,.7f));Text(root.transform,"Port_Value",target?"A":"1",new Vector3(0,2.05f,0),new Vector2(1.3f,.65f),4.5f);return Save(root,target?"Archive_T8_ReceiverPort.prefab":"Archive_T8_EmitterPort.prefab");}
        static GameObject Answer(){var root=new GameObject("Archive_T8_AnswerSeal");Part(root.transform,"Verdict_Stone",octagon,stone,new Vector3(0,.08f,0),new Vector3(1.7f,.20f,1.7f));Part(root.transform,"Choice_Inlay",ring,blue,new Vector3(0,.2f,0),Vector3.one*1.45f);Part(root.transform,"Choice_Center",octagon,ink,new Vector3(0,.19f,0),new Vector3(1.2f,.04f,1.2f));Text(root.transform,"Choice_Name","Function Only",new Vector3(0,.70f,0),new Vector2(3.1f,.6f),3.2f);return Save(root,"Archive_T8_AnswerSeal.prefab");}
        static Mesh Arrow(){string path=Folder+"/Art/Meshes/Archive_T8_DirectedArrow.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh{name="Archive_T8_DirectedArrow"};AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.vertices=new[]{new Vector3(0,0,.28f),new Vector3(-.13f,-.10f,-.18f),new Vector3(.13f,-.10f,-.18f),new Vector3(.13f,.10f,-.18f),new Vector3(-.13f,.10f,-.18f)};mesh.uv=new[]{new Vector2(.5f,1),new Vector2(0,0),new Vector2(1,0),new Vector2(1,1),new Vector2(0,1)};mesh.triangles=new[]{0,1,2,0,2,3,0,3,4,0,4,1,1,3,2,1,4,3};mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);AssetDatabase.SaveAssetIfDirty(mesh);return mesh;}
        static GameObject Save(GameObject root,string file){var asset=PrefabUtility.SaveAsPrefabAsset(root,Prefabs+file);Object.DestroyImmediate(root);return asset;}
        static Material Mat(string name)=>AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Art/Materials/"+name+".mat");
        static Material ColorMat(string name,Color color){var material=Mat(name);if(material==null){material=new Material(Shader.Find("Universal Render Pipeline/Unlit")){name=name,enableInstancing=true};AssetDatabase.CreateAsset(material,Folder+"/Art/Materials/"+name+".mat");}material.SetColor("_BaseColor",color);EditorUtility.SetDirty(material);AssetDatabase.SaveAssetIfDirty(material);return material;}
        static Material CrystalMat(string name,Color color){var material=Mat(name);if(material==null){material=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/FunctionsRelations/CrystalDiamond.mat")){name=name,enableInstancing=true};AssetDatabase.CreateAsset(material,Folder+"/Art/Materials/"+name+".mat");}material.SetFloat("_Surface",0);material.SetFloat("_SrcBlend",1);material.SetFloat("_DstBlend",0);material.SetFloat("_SrcBlendAlpha",1);material.SetFloat("_DstBlendAlpha",0);material.SetFloat("_ZWrite",1);material.SetFloat("_Smoothness",.65f);material.SetColor("_BaseColor",color);material.SetColor("_EmissionColor",color*.15f);material.DisableKeyword("_SURFACE_TYPE_TRANSPARENT");material.SetOverrideTag("RenderType","Opaque");material.renderQueue=2000;EditorUtility.SetDirty(material);AssetDatabase.SaveAssetIfDirty(material);return material;}
        static TMP_Text Text(Transform parent,string name,string value,Vector3 position,Vector2 size,float fontSize){var text=new GameObject(name).AddComponent<TextMeshPro>();text.transform.SetParent(parent,false);text.transform.localPosition=position;text.rectTransform.sizeDelta=size;text.font=font;text.fontSharedMaterial=labels;text.text=value;text.fontSize=fontSize;text.enableAutoSizing=true;text.fontSizeMax=fontSize;text.fontSizeMin=fontSize-1;text.textWrappingMode=TextWrappingModes.NoWrap;text.richText=false;text.alignment=TextAlignmentOptions.Center;text.color=new Color(1,.94f,.79f);text.raycastTarget=false;return text;}
        static Transform Part(Transform parent,string name,Mesh mesh,Material material,Vector3 position,Vector3 scale){var part=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer)).transform;part.SetParent(parent,false);part.localPosition=position;part.localScale=scale;part.GetComponent<MeshFilter>().sharedMesh=mesh;var renderer=part.GetComponent<MeshRenderer>();renderer.sharedMaterial=material;renderer.shadowCastingMode=ShadowCastingMode.Off;return part;}
    }
